    const MARKER: &str = "runtime-symlink-dirs-v2";
    let marker = DATA.join("migrations").join(MARKER);
    if marker.exists() {
        return;
    }

    if let Err(err) = migrate_runtime_symlink_dirs_impl(&marker).await {
        eprintln!("[WARN] migrate: {err}");
    }
